+    private String requiredFileName(String description) {
+        String result;
+        try {
+            result = ruleViolationFileNameStrategy.createRuleFileName(description);
+        } catch (RuntimeException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+        if (result == null || result.isEmpty()) {
+            throw new StoreUpdateFailedException("The RuleViolationFileNameStrategy returned no file name");
+        }
+        return result;
+    }
