+    private List<String> parseLines(String violationsText) {
+        if (violationsText.isEmpty() || containsOnlyLineBreaks(violationsText)) {
+            return Collections.emptyList();
+        }
+        List<String> result = new ArrayList<>();
+        for (String line : UNESCAPED_LINE_BREAK_PATTERN.split(violationsText, -1)) {
+            if (!line.isEmpty() && !containsOnlyCarriageReturns(line)) {
+                result.add(unescape(line));
+            }
+        }
+        return result;
+    }
