    private String propertyForDescription(Properties properties, String description) {
        String exact = properties.getProperty(description);
        if (exact != null) {
            return exact;
        }
        String normalized = normalizeRuleDescription(description);
        for (String storedDescription : properties.stringPropertyNames()) {
            if (normalizeRuleDescription(storedDescription).equals(normalized)) {
                return properties.getProperty(storedDescription);
            }
        }
        return null;
    }

