        }
        String normalized = normalizeRuleDescription(description);
        for (String storedDescription : properties.stringPropertyNames()) {
            if (normalizeRuleDescription(storedDescription).equals(normalized)) {
                return storedDescription;
            }
        }
        return null;
    }

