+        constructorStrategy = ruleViolationFileNameStrategy;
+        strategyWasGivenToConstructor = true;
+    }
+
+    @Override
+    public void initialize(Properties properties) {
+        storeCreationAllowed = Boolean.parseBoolean(properties.getProperty(
+                ALLOW_STORE_CREATION_PROPERTY_NAME, ALLOW_STORE_CREATION_DEFAULT));
+        storeUpdateAllowed = Boolean.parseBoolean(properties.getProperty(
+                ALLOW_STORE_UPDATE_PROPERTY_NAME, ALLOW_STORE_UPDATE_DEFAULT));
+        integrityMode = IntegrityMode.from(properties.getProperty(INTEGRITY_PROPERTY_NAME, INTEGRITY_DEFAULT));
+        if (integrityMode == IntegrityMode.REPAIR && !storeUpdateAllowed) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Integrity repair requires %s.%s=true",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        ruleViolationFileNameStrategy = createStrategy(properties);
+        Path configuredFolder = Paths.get(properties.getProperty(STORE_PATH_PROPERTY_NAME, STORE_PATH_DEFAULT));
+        storeLock = lockFor(configuredFolder);
+
+        synchronized (storeLock) {
+            initializeLocked(configuredFolder);
+        }
+    }
+
+    private RuleViolationFileNameStrategy createStrategy(Properties properties) {
+        String configured = properties.getProperty(FILE_NAMES_PROPERTY_NAME);
+        if (strategyWasGivenToConstructor) {
+            if (configured != null) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Cannot configure %s when a RuleViolationFileNameStrategy was given to the constructor",
+                        FILE_NAMES_PROPERTY_NAME));
+            }
+            return constructorStrategy;
+        }
+
+        if (configured == null || FILE_NAMES_DEFAULT.equals(configured)) {
+            return description -> UUID.randomUUID().toString();
+        }
+        if ("description".equals(configured)) {
+            return TextFileBasedViolationStore::createDescriptionFileName;
+        }
+        try {
+            Class<?> strategyClass = Class.forName(configured);
+            if (!RuleViolationFileNameStrategy.class.isAssignableFrom(strategyClass)) {
+                throw new IllegalArgumentException("does not implement " + RuleViolationFileNameStrategy.class.getName());
+            }
+            Constructor<?> constructor = strategyClass.getConstructor();
+            return (RuleViolationFileNameStrategy) constructor.newInstance();
+        } catch (ClassNotFoundException | NoSuchMethodException | InstantiationException | IllegalAccessException |
+                 InvocationTargetException | ClassCastException | IllegalArgumentException e) {
+            throw new StoreInitializationFailedException(String.format(
+                    "Could not instantiate %s configured by %s=%s; it must implement the strategy and have a public no-argument constructor",
+                    RuleViolationFileNameStrategy.class.getSimpleName(), FILE_NAMES_PROPERTY_NAME, configured), e);
+        }
+    }
+
+    private static String createDescriptionFileName(String description) {
+        Matcher matcher = DESCRIPTION_WORD_PATTERN.matcher(description);
+        String retainedWord = matcher.find() ? matcher.group(1) : "rule";
+        return retainedWord + "-" + sha256(description);
+    }
+
+    private static String sha256(String value) {
+        try {
+            byte[] digest = MessageDigest.getInstance("SHA-256").digest(value.getBytes(StandardCharsets.UTF_8));
+            StringBuilder result = new StringBuilder(digest.length * 2);
+            for (byte oneByte : digest) {
+                result.append(String.format("%02x", oneByte & 0xff));
+            }
+            return result.toString();
+        } catch (NoSuchAlgorithmException e) {
+            throw new IllegalStateException("SHA-256 is not available", e);
+        }
+    }
+
+    private Object lockFor(Path configuredFolder) {
+        try {
+            String key = configuredFolder.toFile().getCanonicalPath();
+            return STORE_LOCKS.computeIfAbsent(key, ignored -> new Object());
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private void initializeLocked(Path configuredFolder) {
+        try {
+            if (!Files.exists(configuredFolder, LinkOption.NOFOLLOW_LINKS)) {
+                if (!storeCreationAllowed) {
+                    throw new StoreInitializationFailedException(String.format(
+                            "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                            ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+                }
+                Files.createDirectories(configuredFolder);
+            }
+            if (!Files.isDirectory(configuredFolder)) {
+                throw new StoreInitializationFailedException("Violation store path is not a directory: " + configuredFolder);
+            }
+
+            storeFolder = configuredFolder.toRealPath();
+            storedRulesFile = storeFolder.resolve(STORED_RULES_FILE_NAME);
+            boolean indexExists = Files.exists(storedRulesFile, LinkOption.NOFOLLOW_LINKS);
+            if (indexExists && !Files.isRegularFile(storedRulesFile, LinkOption.NOFOLLOW_LINKS)) {
+                throw new StoreInitializationFailedException(
+                        "The violation store index is not a regular file directly in the store folder: " + storedRulesFile);
+            }
+            if (!indexExists && !storeCreationAllowed) {
+                throw new StoreInitializationFailedException(String.format(
+                        "Creating new violation store is disabled (enable by configuration %s.%s=true)",
+                        ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_CREATION_PROPERTY_NAME));
+            }
+
+            Properties loaded = indexExists ? loadProperties(storedRulesFile) : new Properties();
+            IntegrityReport report = null;
+            if (integrityMode != IntegrityMode.IGNORE) {
+                report = inspect(loaded);
+            }
+            if (integrityMode == IntegrityMode.FAIL && report.hasProblems()) {
+                throw new StoreInitializationFailedException(report.failureMessage(storeUpdateAllowed));
+            }
+            if (integrityMode == IntegrityMode.REPAIR) {
+                repair(loaded, report);
+            }
+
+            if (!indexExists) {
+                writeProperties(loaded);
+            }
+            storedRules = loaded;
+            log.trace("Initialized {} at {}", TextFileBasedViolationStore.class.getSimpleName(), storedRulesFile);
+        } catch (StoreInitializationFailedException e) {
+            throw e;
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private Properties loadCurrentRules() {
+        try {
+            return loadProperties(storedRulesFile);
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private Properties loadProperties(Path file) throws IOException {
+        Properties result = new Properties();
+        java.io.InputStream inputStream = Files.newInputStream(file);
+        try {
+            result.load(inputStream);
+        } finally {
+            inputStream.close();
+        }
+        return result;
+    }
+
+    @Override
+    public boolean contains(ArchRule rule) {
+        synchronized (storeLock) {
+            storedRules = loadCurrentRules();
+            return storedRules.containsKey(rule.getDescription());
+        }
+    }
+
+    @Override
+    public void save(ArchRule rule, List<String> violations) {
+        log.trace("Storing evaluated rule '{}' with {} violations: {}", rule.getDescription(), violations.size(), violations);
+        if (!storeUpdateAllowed) {
+            throw new StoreUpdateFailedException(String.format(
+                    "Updating frozen violations is disabled (enable by configuration %s.%s=true)",
+                    ViolationStoreFactory.FREEZE_STORE_PROPERTY_NAME, ALLOW_STORE_UPDATE_PROPERTY_NAME));
+        }
+
+        synchronized (storeLock) {
+            Properties current = loadCurrentRules();
+            String description = rule.getDescription();
+            String existingFileName = current.getProperty(description);
+
+            if (violations.isEmpty() && existingFileName == null) {
+                storedRules = current;
+                return;
+            }
+
+            if (violations.isEmpty() && integrityMode == IntegrityMode.REPAIR) {
+                forgetRule(current, description, existingFileName);
+                storedRules = current;
+                return;
+            }
+
+            String fileName = existingFileName;
+            boolean newEntry = fileName == null;
+            if (newEntry) {
+                fileName = requiredFileName(description);
+            }
+            validateSaveTarget(current, description, fileName, newEntry);
+
+            boolean fileExisted = existsWithoutFollowingLinks(storeFolder.resolve(fileName));
+            writeViolations(fileName, violations);
+            if (newEntry) {
+                current.setProperty(description, fileName);
+                try {
+                    writeProperties(current);
+                } catch (StoreUpdateFailedException e) {
+                    if (!fileExisted && !isRecordedByAnotherEntry(current, description, fileName)) {
+                        deleteNamedFileQuietly(fileName);
+                    }
+                    throw e;
+                }
+            }
+            storedRules = current;
+        }
+    }
+
+    private String requiredFileName(String description) {
+        String result;
+        try {
+            result = ruleViolationFileNameStrategy.createRuleFileName(description);
+        } catch (RuntimeException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+        if (result == null || result.isEmpty()) {
+            throw new StoreUpdateFailedException("The RuleViolationFileNameStrategy returned no file name");
+        }
+        return result;
+    }
+
+    private void validateSaveTarget(Properties current, String description, String fileName, boolean newEntry) {
+        if (fileName == null || fileName.isEmpty() || !isDirectFileName(fileName)) {
+            throw new StoreUpdateFailedException("Rule violation file name does not name a direct file in the store folder: " + fileName);
+        }
+        Path path = storeFolder.resolve(fileName);
+        if (isIndex(path)) {
+            throw new StoreUpdateFailedException("Rule violation file name points to the store index: " + fileName);
+        }
+
+        boolean exists = existsWithoutFollowingLinks(path);
+        if (!exists) {
+            if (!newEntry && !current.getProperty(description, "").equals(fileName)) {
+                throw new StoreUpdateFailedException("The rule entry does not record its file name: " + fileName);
+            }
+            return;
+        }
+        Path target = realPathOrNull(path);
+        if (target == null || !Files.isRegularFile(target) || !storeFolder.equals(target.getParent()) || isIndex(target)) {
+            throw new StoreUpdateFailedException("Rule violation file name does not lead to a regular file directly in the store folder: " + fileName);
+        }
+        if (newEntry && !current.containsValue(fileName)) {
+            throw new StoreUpdateFailedException("Rule violation file name names a file not recorded by its entry: " + fileName);
+        }
+        if (!newEntry && !fileName.equals(current.getProperty(description))) {
+            throw new StoreUpdateFailedException("The rule entry does not record its file name: " + fileName);
+        }
+    }
+
+    private void writeViolations(String fileName, List<String> violations) {
+        StringBuilder builder = new StringBuilder();
+        for (String violation : violations) {
+            builder.append(escape(violation)).append("\n");
+        }
+        Path path = storeFolder.resolve(fileName);
+        Path target = realPathOrNull(path);
+        if (target == null) {
+            target = path;
+        }
+        try {
+            Files.write(target, builder.toString().getBytes(StandardCharsets.UTF_8),
+                    StandardOpenOption.CREATE, StandardOpenOption.TRUNCATE_EXISTING, StandardOpenOption.WRITE);
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private String escape(String violation) {
+        return violation.replace("\n", "\\\n");
+    }
+
+    private String unescape(String violation) {
+        return violation.replace("\\\n", "\n");
+    }
+
+    @Override
+    public List<String> getViolations(ArchRule rule) {
+        synchronized (storeLock) {
+            storedRules = loadCurrentRules();
+            String ruleDetailsFileName = storedRules.getProperty(rule.getDescription());
+            checkArgument(ruleDetailsFileName != null, "No rule stored with description '%s'", rule.getDescription());
+            List<String> result = readLines(storeFolder.resolve(ruleDetailsFileName));
+            log.trace("Retrieved stored rule '{}' with {} violations: {}", rule.getDescription(), result.size(), result);
+            return result;
+        }
+    }
+
+    private List<String> readLines(Path file) {
+        try {
+            String violationsText = new String(Files.readAllBytes(file), StandardCharsets.UTF_8);
+            return parseLines(violationsText);
+        } catch (IOException e) {
+            throw new StoreReadException(e);
+        }
+    }
+
+    private List<String> parseLines(String violationsText) {
+        if (violationsText.isEmpty() || containsOnlyLineBreaks(violationsText)) {
+            return Collections.emptyList();
+        }
+        List<String> result = new ArrayList<>();
+        for (String line : UNESCAPED_LINE_BREAK_PATTERN.split(violationsText, -1)) {
+            if (!line.isEmpty() && !containsOnlyCarriageReturns(line)) {
+                result.add(unescape(line));
+            }
+        }
+        return result;
+    }
+
+    private boolean containsOnlyLineBreaks(String value) {
+        for (int i = 0; i < value.length(); i++) {
+            if (value.charAt(i) != '\n' && value.charAt(i) != '\r') {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    private boolean containsOnlyCarriageReturns(String value) {
+        for (int i = 0; i < value.length(); i++) {
+            if (value.charAt(i) != '\r') {
+                return false;
+            }
+        }
+        return true;
+    }
+
+    private void forgetRule(Properties current, String description, String fileName) {
+        if (!isSharedByAnotherEntry(current, description, fileName)) {
+            deleteNamedFile(fileName);
+        }
+        current.remove(description);
+        writeProperties(current);
+    }
+
+    private boolean isSharedByAnotherEntry(Properties properties, String description, String fileName) {
+        for (String otherDescription : properties.stringPropertyNames()) {
+            if (description.equals(otherDescription)) {
+                continue;
+            }
+            String otherName = properties.getProperty(otherDescription);
+            if (fileName.equals(otherName) || namesReachSameFile(fileName, otherName)) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private boolean isRecordedByAnotherEntry(Properties properties, String description, String fileName) {
+        for (String otherDescription : properties.stringPropertyNames()) {
+            if (!description.equals(otherDescription) && fileName.equals(properties.getProperty(otherDescription))) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    private boolean namesReachSameFile(String firstName, String secondName) {
+        Path first = resolveAnyTarget(firstName);
+        Path second = resolveAnyTarget(secondName);
+        return first != null && second != null && sameFile(first, second);
+    }
+
+    private void deleteNamedFile(String fileName) {
+        if (!isDirectFileName(fileName)) {
+            return;
+        }
+        Path path = storeFolder.resolve(fileName);
+        if (!existsWithoutFollowingLinks(path)) {
+            return;
+        }
+        Path target = realPathOrNull(path);
+        if (target == null) {
+            return;
+        }
+        try {
+            Files.delete(target);
+            if (!target.equals(path)) {
+                Files.deleteIfExists(path);
+            }
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        }
+    }
+
+    private void deleteNamedFileQuietly(String fileName) {
+        try {
+            deleteNamedFile(fileName);
+        } catch (RuntimeException ignored) {
+            // The original update failure is the useful error for the caller.
+        }
+    }
+
+    private void writeProperties(Properties properties) {
+        Path temporary = null;
+        try {
+            temporary = Files.createTempFile(storeFolder, ".stored.rules-", ".tmp");
+            java.io.OutputStream outputStream = Files.newOutputStream(temporary);
+            try {
+                properties.store(outputStream, "");
+            } finally {
+                outputStream.close();
+            }
+            moveReplacing(temporary, storedRulesFile);
+            temporary = null;
+        } catch (IOException e) {
+            throw new StoreUpdateFailedException(e);
+        } finally {
+            if (temporary != null) {
+                try {
+                    Files.deleteIfExists(temporary);
+                } catch (IOException ignored) {
+                    // Best effort cleanup of a temporary file.
+                }
+            }
+        }
+    }
+
+    private void moveReplacing(Path source, Path target) throws IOException {
+        try {
+            Files.move(source, target, StandardCopyOption.REPLACE_EXISTING, StandardCopyOption.ATOMIC_MOVE);
+        } catch (IOException e) {
+            Files.move(source, target, StandardCopyOption.REPLACE_EXISTING);
+        }
+    }
+
+    private IntegrityReport inspect(Properties properties) throws IOException {
+        List<EntryAnalysis> entries = new ArrayList<>();
+        for (String description : properties.stringPropertyNames()) {
+            String fileName = properties.getProperty(description);
+            EntryAnalysis entry = new EntryAnalysis(description, fileName);
+            entry.derivedName = requiredFileNameForInspection(description);
+            entry.misplaced = !entry.fileName.equals(entry.derivedName);
+            entries.add(entry);
+        }
+
+        Map<String, List<EntryAnalysis>> names = new HashMap<>();
+        for (EntryAnalysis entry : entries) {
+            names.computeIfAbsent(entry.fileName, ignored -> new ArrayList<>()).add(entry);
+            entry.target = resolveAnyTarget(entry.fileName);
+            entry.broken = !isRegularFileDirectlyInFolder(entry.fileName, entry.target);
+            if (entry.target != null && Files.isRegularFile(entry.target)) {
+                try {
+                    entry.resolved = readLines(entry.target).isEmpty();
+                } catch (StoreReadException e) {
+                    entry.broken = true;
+                }
+            }
+        }
+        for (List<EntryAnalysis> sameName : names.values()) {
+            if (sameName.size() > 1) {
+                for (EntryAnalysis entry : sameName) {
+                    entry.shared = true;
+                }
+            }
+        }
+        for (int i = 0; i < entries.size(); i++) {
+            for (int j = i + 1; j < entries.size(); j++) {
+                EntryAnalysis first = entries.get(i);
+                EntryAnalysis second = entries.get(j);
+                if (first.target != null && second.target != null && sameFile(first.target, second.target)) {
+                    first.shared = true;
+                    second.shared = true;
+                }
+            }
+        }
+
+        Map<String, List<EntryAnalysis>> derivedNames = new HashMap<>();
+        for (EntryAnalysis entry : entries) {
+            derivedNames.computeIfAbsent(entry.derivedName, ignored -> new ArrayList<>()).add(entry);
+        }
+        for (List<EntryAnalysis> collision : derivedNames.values()) {
+            if (collision.size() > 1) {
+                for (EntryAnalysis entry : collision) {
+                    entry.colliding = true;
+                }
+            }
+        }
+        for (EntryAnalysis entry : entries) {
+            if (entry.misplaced) {
+                entry.occupied = isOccupied(entry.derivedName, properties);
+            }
+        }
+
+        List<String> unownedFiles = new ArrayList<>();
+        try (DirectoryStream<Path> children = Files.newDirectoryStream(storeFolder)) {
+            for (Path child : children) {
+                if (STORED_RULES_FILE_NAME.equals(child.getFileName().toString()) ||
+                        !Files.isRegularFile(child, LinkOption.NOFOLLOW_LINKS)) {
+                    continue;
+                }
+                boolean owned = false;
+                for (EntryAnalysis entry : entries) {
+                    if (entry.target != null && sameFile(child, entry.target)) {
+                        owned = true;
+                        break;
+                    }
+                }
+                if (!owned) {
+                    unownedFiles.add(child.getFileName().toString());
+                }
+            }
+        }
+        Collections.sort(unownedFiles);
+        return new IntegrityReport(entries, unownedFiles);
+    }
+
+    private String requiredFileNameForInspection(String description) {
+        return requiredFileName(description);
+    }
+
+    private boolean isOccupied(String derivedName, Properties properties) {
+        if (!isDirectFileName(derivedName)) {
+            return true;
+        }
+        for (String description : properties.stringPropertyNames()) {
+            if (derivedName.equals(properties.getProperty(description))) {
+                return true;
+            }
+        }
+        return existsWithoutFollowingLinks(storeFolder.resolve(derivedName));
+    }
+
+    private void repair(Properties properties, IntegrityReport report) {
+        for (EntryAnalysis entry : report.entries) {
+            if (entry.shared) {
+                continue;
+            }
+            if (entry.broken) {
+                properties.remove(entry.description);
+            } else if (entry.resolved) {
+                deleteNamedFile(entry.fileName);
+                properties.remove(entry.description);
+            } else if (entry.misplaced && !entry.colliding && !entry.occupied) {
+                moveEntry(entry);
+                properties.setProperty(entry.description, entry.derivedName);
+            }
+        }
+        if (report.entriesChanged(properties)) {
+            writeProperties(properties);
+        }
+    }
+
+    private void moveEntry(EntryAnalysis entry) {
+        if (!isDirectFileName(entry.derivedName) || entry.target == null) {
+            return;
+        }
+        Path destination = storeFolder.resolve(entry.derivedName);
+        try {
+            Files.move(entry.target, destination);
+            Path oldPath = storeFolder.resolve(entry.fileName);
+            if (!entry.target.equals(oldPath)) {
+                Files.deleteIfExists(oldPath);
+            }
+        } catch (IOException e) {
+            throw new StoreInitializationFailedException(e);
+        }
+    }
+
+    private boolean isRegularFileDirectlyInFolder(String fileName, Path target) {
+        return isDirectFileName(fileName) && target != null && Files.isRegularFile(target)
+                && storeFolder.equals(target.getParent()) && !isIndex(target);
+    }
+
+    private boolean isDirectFileName(String fileName) {
+        if (fileName == null || fileName.isEmpty()) {
+            return false;
+        }
+        try {
+            Path path = Paths.get(fileName);
+            return !path.isAbsolute() && path.getNameCount() == 1 && !".".equals(fileName) && !"..".equals(fileName);
+        } catch (InvalidPathException e) {
+            return false;
+        }
+    }
+
+    private boolean isIndex(Path path) {
+        try {
+            return Files.exists(path, LinkOption.NOFOLLOW_LINKS) && sameFile(path, storedRulesFile);
+        } catch (RuntimeException e) {
+            return false;
+        }
+    }
+
+    private Path resolveAnyTarget(String fileName) {
+        if (!isDirectFileName(fileName)) {
+            return null;
+        }
+        Path path = storeFolder.resolve(fileName);
+        if (!existsWithoutFollowingLinks(path)) {
+            return null;
+        }
+        return realPathOrNull(path);
+    }
+
+    private Path realPathOrNull(Path path) {
+        try {
+            return path.toRealPath();
+        } catch (IOException | SecurityException e) {
+            return null;
+        }
+    }
+
+    private boolean existsWithoutFollowingLinks(Path path) {
+        return Files.exists(path, LinkOption.NOFOLLOW_LINKS);
+    }
+
+    private boolean sameFile(Path first, Path second) {
+        try {
+            return Files.isSameFile(first, second);
+        } catch (IOException e) {
+            return first.toAbsolutePath().normalize().equals(second.toAbsolutePath().normalize());
+        }
+    }
+
+    private enum IntegrityMode {
+        IGNORE,
+        REPAIR,
+        FAIL;
+
+        static IntegrityMode from(String configured) {
+            if ("ignore".equals(configured)) {
+                return IGNORE;
+            }
+            if ("repair".equals(configured)) {
+                return REPAIR;
+            }
+            if ("fail".equals(configured)) {
+                return FAIL;
+            }
+            throw new StoreInitializationFailedException(
+                    "Invalid default.integrity value '" + configured + "'; accepted values are repair, fail and ignore");
+        }
+    }
+
+    private static class EntryAnalysis {
+        private final String description;
+        private final String fileName;
+        private String derivedName;
+        private Path target;
+        private boolean broken;
+        private boolean resolved;
+        private boolean shared;
+        private boolean misplaced;
+        private boolean colliding;
+        private boolean occupied;
+
+        private EntryAnalysis(String description, String fileName) {
+            this.description = description;
+            this.fileName = fileName;
+        }
+
+        private boolean hasProblem() {
+            return broken || resolved || shared || misplaced || colliding || occupied;
+        }
+    }
+
+    private class IntegrityReport {
+        private final List<EntryAnalysis> entries;
+        private final List<String> unownedFiles;
+        private final Map<String, String> originalNames = new HashMap<>();
+
+        private IntegrityReport(List<EntryAnalysis> entries, List<String> unownedFiles) {
+            this.entries = entries;
+            this.unownedFiles = unownedFiles;
+            for (EntryAnalysis entry : entries) {
+                originalNames.put(entry.description, entry.fileName);
+            }
+        }
+
+        private boolean hasProblems() {
+            for (EntryAnalysis entry : entries) {
+                if (entry.hasProblem()) {
+                    return true;
+                }
+            }
+            return !unownedFiles.isEmpty();
+        }
+
+        private boolean entriesChanged(Properties properties) {
+            if (properties.size() != originalNames.size()) {
+                return true;
+            }
+            for (Map.Entry<String, String> original : originalNames.entrySet()) {
+                if (!original.getValue().equals(properties.getProperty(original.getKey()))) {
+                    return true;
+                }
+            }
+            return false;
+        }
+
+        private String failureMessage(boolean allowUpdate) {
+            StringBuilder result = new StringBuilder("Violation store integrity check failed (default.allowStoreUpdate=")
+                    .append(allowUpdate).append("):");
